<script setup lang="ts">
const token=ref(''),csrf=ref(''),error=ref(''),busy=ref(false),ready=ref(false);const member=useMember();
onMounted(async()=>{const fragment=new URLSearchParams(location.hash.slice(1));token.value=fragment.get('token')||location.hash.slice(1);history.replaceState(history.state,'',location.pathname);if(!token.value){error.value='This link is missing its credential. Request another sign-in link.';return;}try{csrf.value=(await $fetch<{data:{csrfToken:string}}>('/api/v1/auth/preflight')).data.csrfToken;ready.value=true;}catch{error.value='The confirmation service is unavailable. Reload to try again or request another link.';}});
async function confirm(){if(!ready.value)return;busy.value=true;error.value='';try{const result=await $fetch<{data:{returnPath:string}}>('/api/v1/auth/confirm',{method:'POST',body:{token:token.value},headers:{'X-CSRF-Token':csrf.value}});token.value='';csrf.value='';await member.refresh();window.dispatchEvent(new Event('aggregator:signed-in'));try{const native=JSON.parse(localStorage.getItem('aggregator-native-pending')||'null');if(native?.expires>Date.now()&&/^[a-f0-9-]{36}$/.test(native.id)){await navigateTo({path:'/auth/native',query:{id:native.id}});return;}}catch{/* A broken optional continuation never changes identity. */}const returnPath=takeReaderReturn()||result.data.returnPath;const interests=(await $fetch<{data:{status:string}}>('/api/v1/me/interests')).data;if(interests.status==='not_started'){await navigateTo({path:'/interests',query:{setup:'1',returnTo:returnPath}});return;}await navigateTo(readerReturn(returnPath)||'/library');}catch{error.value='This link is expired, already used or could not be confirmed. Request a fresh link.';}finally{busy.value=false;}}
useHead({title:'Confirm sign in — The Aggregator',meta:[{name:'referrer',content:'no-referrer'}]});
</script>
<template><MemberFrame><h1>Confirm your sign-in</h1><p>Opening this page does not sign you in. Continue only if you requested this link for this local demonstration.</p><button class="control control--primary" :disabled="!ready||busy" @click="confirm">{{ busy?'Confirming…':'Confirm sign in' }}</button><p class="member-status" role="alert">{{ error }}</p><NuxtLink to="/sign-in">Request another link</NuxtLink><noscript><p>Local sign-in requires JavaScript to keep the link credential out of the server-rendered page. Anonymous articles and sources remain readable.</p></noscript></MemberFrame></template>

